  // The item that reached Get Run Status (through Poll Wait) is the current runner state.
  if ($('Poll Wait').isExecuted) return $('Poll Wait').last().json;
  if ($('Capture Run Response').isExecuted) return $('Capture Run Response').last().json;
  return $('Normalize Request').last().json;
